import React, { useState, useReducer } from "react";

import Card from "../UI/Card/Card";
import classes from "./Login.module.css";
import Button from "../UI/Button/Button";

const emailReducer = (state, action) => {
  if (action.type === "EMAIL_USER_INPUT") {
    return { value: action.value, valid: action.value.includes("@") };
  }
  if (action.type === "EMAIL_INPUT_BLUR") {
    return { value: state.value, valid: state.value.includes("@") };
  }
  return { value: "", valid: false };
};

const formReducer = (state, action) => {
  if (action.type === "USER_INPUT") {
    const passIsValid = action.password.trim().length > 6;
    return {
      password: action.password,
      passwordValid: passIsValid,
      formValid: emailState.valid && passIsValid,
    };
  }
  if (action.type === "INPUT_BLUR") {
    return { value: state.value, valid: state.value.includes("@") };
  }
  return { password: "", passwordValid: false, formValid: false };
};

const Login = (props) => {
  const [emailState, dispatchEmail] = useReducer(emailReducer, {

  });

  const [formState, dispathForm] = useReducer(formReducer, {
    value: "",
    valid: false,
    password: "",
    passwordValid: false,
    formValid: false,
  });

  const emailChangeHandler = (event) => {
    dispatchEmail({ type: "EMAIL_USER_INPUT", value: event.target.value });

    dispathForm({ type: "USER_INPUT" });
    setFormIsValid(emailState.valid && enteredPassword.trim().length > 6);
  };

  const validateEmailHandler = () => {
    dispatchEmail({ type: "EMAIL_INPUT_BLUR" });
  };

  const passwordChangeHandler = (event) => {
    setEnteredPassword(event.target.value);

    setFormIsValid();
  };

  const validatePasswordHandler = () => {
    setPasswordIsValid(enteredPassword.trim().length > 6);
  };

  const submitHandler = (event) => {
    event.preventDefault();
    props.onLogin(emailState.value, enteredPassword);
  };

  return (
    <Card className={classes.login}>
      <form onSubmit={submitHandler}>
        <div
          className={`${classes.control} ${
            emailState.valid === false ? classes.invalid : ""
          }`}
        >
          <label htmlFor="email">E-Mail</label>
          <input
            type="email"
            id="email"
            value={emailState.value}
            onChange={emailChangeHandler}
            onBlur={validateEmailHandler}
          />
        </div>
        <div
          className={`${classes.control} ${
            passwordIsValid === false ? classes.invalid : ""
          }`}
        >
          <label htmlFor="password">Password</label>
          <input
            type="password"
            id="password"
            value={enteredPassword}
            onChange={passwordChangeHandler}
            onBlur={validatePasswordHandler}
          />
        </div>
        <div className={classes.actions}>
          <Button type="submit" className={classes.btn} disabled={!formIsValid}>
            Login
          </Button>
        </div>
      </form>
    </Card>
  );
};

export default Login;
